1	// Demo driver: replay a filtered ITCH file through the parser at a chosen
2	// speed. Plan: .claude/plans/itch-replay-clock.md, step 3.
3	//
4	// Usage: replay_main <file> <maxspeed|wallclock|step> [speed]
5	//   maxspeed   drain as fast as possible (batch)
6	//   wallclock  pace by the messages' own ITCH timestamps * 1/speed
7	//   step       drain one message at a time via ReplayClock::step()
8	//
9	// The sink re-frames each delivered message and runs it through
10	// itch::parse_buffer, so this exercises the exact parser path a live signal
11	// loop would. On the committed AAPL fixture (269,742 messages) maxspeed
12	// replays the full day in well under a second on an M-series laptop.
13	
14	#include "replay_clock.hpp"
15	#include "itch_parser.hpp"
16	
17	#include <chrono>
18	#include <cstdio>
19	#include <cstring>
20	#include <string>
21	#include <vector>
22	
23	int main(int argc, char** argv) {
24	    if (argc < 3) {
25	        std::fprintf(stderr,
26	            "usage: %s <file> <maxspeed|wallclock|step> [speed]\n"
27	            "  maxspeed   batch drain, no pacing\n"
28	            "  wallclock  pace by ITCH timestamps / speed (speed default 1.0)\n"
29	            "  step       one message per step() call\n",
30	            argv[0]);
31	        return 2;
32	    }
33	    const std::string path = argv[1];
34	    const std::string mode_arg = argv[2];
35	    const double speed = argc >= 4 ? std::atof(argv[3]) : 1.0;
36	
37	    itch::ReplayMode mode;
38	    if (mode_arg == "maxspeed") mode = itch::ReplayMode::MaxSpeed;
39	    else if (mode_arg == "wallclock") mode = itch::ReplayMode::WallClock;
40	    else if (mode_arg == "step") mode = itch::ReplayMode::SingleStep;
41	    else {
42	        std::fprintf(stderr, "unknown mode '%s'\n", mode_arg.c_str());
43	        return 2;
44	    }
45	
46	    itch::ReplayClock clock = [&] {
47	        try {
48	            return itch::ReplayClock::from_file(path);
49	        } catch (const std::exception& e) {
50	            std::fprintf(stderr, "%s\n", e.what());
51	            std::exit(2);
52	        }
53	    }();
54	
55	    // Accumulate parser stats across per-message re-framed parses. The 2-byte
56	    // length prefix is stripped by the clock, so we restore it in a single
57	    // reusable buffer (ITCH message lengths fit in uint16 -> <= 65535 bytes).
58	    std::vector<uint8_t> framed(2 + 65535);
59	    itch::ParseStats parse_total;
60	    itch::MessageVisitor visitor;  // empty: parse_buffer still counts by type
61	
62	    auto sink = [&](const uint8_t* msg, uint16_t len, uint64_t /*ts*/) {
63	        framed[0] = static_cast<uint8_t>(len >> 8);
64	        framed[1] = static_cast<uint8_t>(len & 0xFF);
65	        std::memcpy(framed.data() + 2, msg, len);
66	        const itch::ParseStats s =
67	            itch::parse_buffer(framed.data(), 2u + len, visitor);
68	        parse_total.add_count     += s.add_count;
69	        parse_total.execute_count += s.execute_count;
70	        parse_total.cancel_count  += s.cancel_count;
71	        parse_total.delete_count  += s.delete_count;
72	        parse_total.replace_count += s.replace_count;
73	        parse_total.skipped_count += s.skipped_count;
74	        parse_total.error_count   += s.error_count;
75	    };
76	
77	    const auto t0 = std::chrono::steady_clock::now();
78	    try {
79	        if (mode == itch::ReplayMode::SingleStep) {
80	            while (clock.step(sink)) { /* one message per iteration */ }
81	        } else {
82	            clock.run(sink, mode, speed);
